use super::*;

/// Stage 1: Partial P separation (3x2x2x1 block)
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash)]
pub struct Stage1 {
    /// For each edge and ridge, 1 bit indicating whether it belongs in the P
    /// slice.
    pub er_p: u64, // (u32, u24)
}

impl Default for Stage1 {
    fn default() -> Self {
        Self::SOLVED
    }
}

impl Stage1 {
    const SOLVED: Self = Self {
        er_p: 0x00003fc00000f000,
    };
    const STEP1_TARGET: Self = Self {
        er_p: 0x000004c000001000,
    };
    const STEP2_TARGET: Self = Self {
        er_p: 0x00000dc000003000,
    };

    pub fn is_step1_solved(self) -> bool {
        self.er_p & Self::STEP1_TARGET.er_p == Self::STEP1_TARGET.er_p
    }
    pub fn is_step2_solved(self) -> bool {
        self.er_p & Self::STEP2_TARGET.er_p == Self::STEP2_TARGET.er_p
    }
    pub fn is_solved(self) -> bool {
        self.er_p & Self::SOLVED.er_p == Self::SOLVED.er_p
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::lut_gen::*;

    fn pieces() -> Vec<Vec4> {
        std::iter::chain(PieceType::Edge.iter(), PieceType::Ridge.iter()).collect()
    }

    fn println_target_state(name: &str, condition: fn(Vec4) -> bool) {
        println!(
            "const {name}: Self = Self {{ er_p: 0x{:016x} }};",
            crate::util::collect_bits(pieces().into_iter().map(condition)),
        );
    }

    #[test]
    fn print_stage1_targets() {
        println_target_state("SOLVED", |v| v[W] == 0 && v[Z] <= 0);
        println_target_state("STEP1_TARGET", |v| {
            v[W] == 0 && v[Z] <= 0 && v[Y] <= 0 && v[X] <= 0
        });
        println_target_state("STEP2_TARGET", |v| v[W] == 0 && v[Z] <= 0 && v[Y] <= 0);
    }

    #[test]
    fn lutgen_stage1_er_p() {
        let lut = PermutationLut::new(&pieces());
        println!("{}", lut.to_rust_code(64, 0, 1, "er_p", "twist"));
    }
}

